```sql
WITH ranked AS (
 SELECT *, ROW_NUMBER() OVER (
  PARTITION BY category ORDER BY amount DESC, product
 ) AS position
 FROM exercise_sales
)
SELECT category, product, amount FROM ranked
WHERE position = 1 ORDER BY category;
```

